import os
import requests


class AzureSpeechClient:
    def __init__(self, region: str, api_key: str):
        self.region = region
        self.api_key = api_key
        self.base_url = f"https://{self.region}.api.cognitive.microsoft.com/speechtotext/v3.2" # Updated API version to 3.2 based on documentation
        self.headers = {
            'Ocp-Apim-Subscription-Key': self.api_key,
            'Content-Type': 'application/json'
        }

    def _make_request(self, method: str, endpoint: str, json_payload=None, params=None):
        url = f"{self.base_url}/{endpoint}"
        response = requests.request(method, url, headers=self.headers, json=json_payload, params=params, timeout=30)
        response.raise_for_status()
        return response.json()

    def submit_transcription_job(self, display_name: str, locale: str, content_urls: list, diarization_enabled: bool = False, word_level_timestamps_enabled: bool = False):
        properties = {}
        if diarization_enabled:
            properties['diarizationEnabled'] = True
        if word_level_timestamps_enabled:
            properties['wordLevelTimestampsEnabled'] = True

        payload = {
            'displayName': display_name,
            'locale': locale,
            'contentUrls': content_urls,
            'properties': properties
        }
        return self._make_request('POST', 'transcriptions', json_payload=payload)

    def get_transcription_job(self, job_id: str):
        return self._make_request('GET', f'transcriptions/{job_id}')

    def get_transcription_results(self, job_id: str):
        return self._make_request('GET', f'transcriptions/{job_id}/files')

import os
import time
import requests
from speech_client import AzureSpeechClient
from speech_models import TranscriptionJobResult, FullTranscriptionResult, normalize_transcription_job_result, parse_full_transcription_result

def poll_transcription(job_id: str, config=None) -> FullTranscriptionResult:
    config = config or {}
    region = config.get('region') or os.environ.get('AZURE_SPEECH_REGION')
    api_key = config.get('api_key') or os.environ.get('AZURE_SPEECH_KEY')

    if not region or not api_key:
        raise ValueError("Azure Speech region and API key must be provided or set as environment variables.")

    client = AzureSpeechClient(region, api_key)

    while True:
        job_status_response = client.get_transcription_job(job_id)
        job_result: TranscriptionJobResult = normalize_transcription_job_result(job_status_response)

        if job_result.status == 'Succeeded':
            # Get the files associated with the job
            files_response = client.get_transcription_results(job_id)
            transcript_file_url = None
            for file_info in files_response['values']:
                if file_info['kind'] == 'Transcription':
                    transcript_file_url = file_info['links']['content']
                    break

            if transcript_file_url:
                # Fetch the actual transcript content
                transcript_content_response = requests.get(
                    transcript_file_url,
                    headers={'Ocp-Apim-Subscription-Key': api_key},
                    timeout=30
                )
                transcript_content_response.raise_for_status()
                return parse_full_transcription_result(transcript_content_response.json())
            else:
                raise RuntimeError(f"No transcription file found for job {job_id}")
        elif job_result.status == 'Failed':
            raise RuntimeError(f"Transcription job {job_id} failed.")
        elif job_result.status in ['Running', 'NotStarted', 'Waiting', 'Succeeded']:
            # Continue polling
            time.sleep(5)  # Wait for 5 seconds before polling again
        else:
            raise RuntimeError(f"Unknown job status: {job_result.status} for job {job_id}")

import os
import requests
from typing import List, Dict, Any

def translate_transcript(text_segments: List[str], target_language: str, config=None) -> List[Dict[str, Any]]:
    config = config or {}
    api_key = config.get('azure_translator_key') or os.environ.get('AZURE_TRANSLATOR_KEY')
    endpoint = config.get('azure_translator_endpoint') or os.environ.get('AZURE_TRANSLATOR_ENDPOINT')
    region = config.get('azure_translator_region') or os.environ.get('AZURE_TRANSLATOR_REGION')

    if not api_key or not endpoint or not region:
        raise ValueError("Azure Translator API key, endpoint, and region must be provided or set as environment variables.")

    path = '/translate'
    constructed_url = endpoint + path

    headers = {
        'Ocp-Apim-Subscription-Key': api_key,
        'Ocp-Apim-Subscription-Region': region,
        'Content-type': 'application/json'
    }

    params = {
        'api-version': '3.0',
        'to': target_language
    }

    body = [{'text': segment} for segment in text_segments]

    response = requests.post(constructed_url, params=params, headers=headers, json=body, timeout=30)
    response.raise_for_status()
    return response.json()

import os
import requests
from typing import Dict, Any, List

def moderate_transcript(text_content: str, config=None) -> Dict[str, Any]:
    config = config or {}
    api_key = config.get('azure_content_moderator_key') or os.environ.get('AZURE_CONTENT_MODERATOR_KEY')
    endpoint = config.get('azure_content_moderator_endpoint') or os.environ.get('AZURE_CONTENT_MODERATOR_ENDPOINT')

    if not api_key or not endpoint:
        raise ValueError("Azure Content Moderator API key and endpoint must be provided or set as environment variables.")

    text_moderation_url = f"{endpoint}/contentmoderator/moderate/v1.0/ProcessText/Screen/?autocorrect=true"

    headers = {
        'Ocp-Apim-Subscription-Key': api_key,
        'Content-Type': 'text/plain'
    }

    response = requests.post(text_moderation_url, headers=headers, data=text_content.encode('utf-8'), timeout=30)
    response.raise_for_status()
    return response.json()
